VkResult VkEncoder::vkEnumeratePhysicalDeviceGroups(
    VkInstance instance, uint32_t* pPhysicalDeviceGroupCount,
    VkPhysicalDeviceGroupProperties* pPhysicalDeviceGroupProperties, uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    size_t count = 0;
    count += 2 * 8;
    if (pPhysicalDeviceGroupCount) {
        count += sizeof(uint32_t);
    }
    count += 8;
    if (pPhysicalDeviceGroupProperties) {
        if (pPhysicalDeviceGroupCount) {
            for (uint32_t i = 0; i < (uint32_t)(*pPhysicalDeviceGroupCount); ++i) {
                count_VkPhysicalDeviceGroupProperties(
                    sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                    (VkPhysicalDeviceGroupProperties*)(pPhysicalDeviceGroupProperties + i), &count);
            }
        }
    }
    uint8_t* streamPtr = reservePacket(stream, OP_vkEnumeratePhysicalDeviceGroups, count,
                                       queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_instance_to_host_u64(instance));
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pPhysicalDeviceGroupCount);
    if (pPhysicalDeviceGroupCount) {
        writeStreamBytes(&streamPtr, pPhysicalDeviceGroupCount, sizeof(uint32_t));
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pPhysicalDeviceGroupProperties);
    if (pPhysicalDeviceGroupProperties) {
        for (uint32_t i = 0; i < (uint32_t)(*pPhysicalDeviceGroupCount); ++i) {
            reservedmarshal_VkPhysicalDeviceGroupProperties(
                stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                (VkPhysicalDeviceGroupProperties*)(pPhysicalDeviceGroupProperties + i), &streamPtr);
        }
    }
    uint64_t check_pPhysicalDeviceGroupCount = stream->getBe64();
    if (pPhysicalDeviceGroupCount) {
        if (!(check_pPhysicalDeviceGroupCount)) {
            GFXSTREAM_ERROR("fatal: pPhysicalDeviceGroupCount inconsistent between guest and host");
        }
        stream->read(pPhysicalDeviceGroupCount, sizeof(uint32_t));
    }
    uint64_t check_pPhysicalDeviceGroupProperties = stream->getBe64();
    if (pPhysicalDeviceGroupProperties) {
        if (!(check_pPhysicalDeviceGroupProperties)) {
            GFXSTREAM_ERROR(
                "fatal: pPhysicalDeviceGroupProperties inconsistent between guest and host");
        }
        if (pPhysicalDeviceGroupCount) {
            for (uint32_t i = 0; i < (uint32_t)(*pPhysicalDeviceGroupCount); ++i) {
                unmarshal_VkPhysicalDeviceGroupProperties(
                    stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                    (VkPhysicalDeviceGroupProperties*)(pPhysicalDeviceGroupProperties + i));
            }
        }
    }
    if (pPhysicalDeviceGroupCount) {
        if (pPhysicalDeviceGroupProperties) {
            for (uint32_t i = 0; i < (uint32_t)(*pPhysicalDeviceGroupCount); ++i) {
                transform_fromhost_VkPhysicalDeviceGroupProperties(
                    sResourceTracker,
                    (VkPhysicalDeviceGroupProperties*)(pPhysicalDeviceGroupProperties + i));
            }
        }
    }
    VkResult vkEnumeratePhysicalDeviceGroups_VkResult_return = (VkResult)0;
    stream->read(&vkEnumeratePhysicalDeviceGroups_VkResult_return, sizeof(VkResult));
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
    return vkEnumeratePhysicalDeviceGroups_VkResult_return;
}

