void VkEncoder::vkCmdBindVertexBuffers2(VkCommandBuffer commandBuffer, uint32_t firstBinding,
                                        uint32_t bindingCount, const VkBuffer* pBuffers,
                                        const VkDeviceSize* pOffsets, const VkDeviceSize* pSizes,
                                        const VkDeviceSize* pStrides, uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    size_t count = 0;
    count += 8;
    count += 2 * sizeof(uint32_t);
    count += 8;
    if (pBuffers) {
        if (bindingCount) {
            count += bindingCount * 8;
        }
    }
    count += bindingCount * sizeof(const VkDeviceSize);
    count += 8;
    if (pSizes) {
        count += bindingCount * sizeof(const VkDeviceSize);
    }
    count += 8;
    if (pStrides) {
        count += bindingCount * sizeof(const VkDeviceSize);
    }
    uint8_t* streamPtr =
        reserveCmdPacket(stream, OP_vkCmdBindVertexBuffers2, count, queueSubmitWithCommandsEnabled);
    if (!queueSubmitWithCommandsEnabled) {
        writeStreamVal(&streamPtr, gfxstream_vk_command_buffer_to_host_u64(commandBuffer));
    }
    writeStreamBytes(&streamPtr, &firstBinding, sizeof(uint32_t));
    writeStreamBytes(&streamPtr, &bindingCount, sizeof(uint32_t));
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pBuffers);
    if (pBuffers) {
        if (bindingCount) {
            for (uint32_t k = 0; k < bindingCount; ++k) {
                writeStreamVal(&streamPtr, gfxstream_vk_buffer_to_host_u64(pBuffers[k]));
            }
        }
    }
    if (bindingCount > 0) {
        writeStreamBytes(&streamPtr, pOffsets, bindingCount * sizeof(const VkDeviceSize));
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pSizes);
    if (pSizes) {
        if (bindingCount > 0) {
            writeStreamBytes(&streamPtr, pSizes, bindingCount * sizeof(const VkDeviceSize));
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pStrides);
    if (pStrides) {
        if (bindingCount > 0) {
            writeStreamBytes(&streamPtr, pStrides, bindingCount * sizeof(const VkDeviceSize));
        }
    }
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

