void VkEncoder::vkCollectDescriptorPoolIdsGOOGLE(VkDevice device, VkDescriptorPool descriptorPool,
                                                 uint32_t* pPoolIdCount, uint64_t* pPoolIds,
                                                 uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    size_t count = 0;
    count += 2 * 8;
    count += sizeof(uint32_t);
    count += 8;
    if (pPoolIds) {
        if (pPoolIdCount) {
            count += (*pPoolIdCount) * sizeof(uint64_t);
        }
    }
    uint8_t* streamPtr = reservePacket(stream, OP_vkCollectDescriptorPoolIdsGOOGLE, count,
                                       queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_device_to_host_u64(device));
    writeStreamVal(&streamPtr, gfxstream_vk_descriptor_pool_to_host_u64(descriptorPool));
    writeStreamBytes(&streamPtr, pPoolIdCount, sizeof(uint32_t));
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pPoolIds);
    if (pPoolIds) {
        if ((*pPoolIdCount) > 0) {
            writeStreamBytes(&streamPtr, pPoolIds, (*pPoolIdCount) * sizeof(uint64_t));
        }
    }
    stream->read(pPoolIdCount, sizeof(uint32_t));
    uint64_t check_pPoolIds = stream->getBe64();
    if (pPoolIds) {
        if (!(check_pPoolIds)) {
            GFXSTREAM_ERROR("fatal: pPoolIds inconsistent between guest and host");
        }
        stream->read(pPoolIds, (*pPoolIdCount) * sizeof(uint64_t));
    }
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

