void VkEncoder::vkUpdateDescriptorSetWithTemplateSized2GOOGLE(
    VkDevice device, VkDescriptorSet descriptorSet,
    VkDescriptorUpdateTemplate descriptorUpdateTemplate, uint32_t imageInfoCount,
    uint32_t bufferInfoCount, uint32_t bufferViewCount, uint32_t inlineUniformBlockCount,
    const uint32_t* pImageInfoEntryIndices, const uint32_t* pBufferInfoEntryIndices,
    const uint32_t* pBufferViewEntryIndices, const VkDescriptorImageInfo* pImageInfos,
    const VkDescriptorBufferInfo* pBufferInfos, const VkBufferView* pBufferViews,
    const uint8_t* pInlineUniformBlockData, uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    size_t count = 0;
    count += 3 * 8;
    count += 4 * sizeof(uint32_t);
    count += 8;
    if (pImageInfoEntryIndices) {
        count += imageInfoCount * sizeof(const uint32_t);
    }
    count += 8;
    if (pBufferInfoEntryIndices) {
        count += bufferInfoCount * sizeof(const uint32_t);
    }
    count += 8;
    if (pBufferViewEntryIndices) {
        count += bufferViewCount * sizeof(const uint32_t);
    }
    count += 8;
    if (pImageInfos) {
        for (uint32_t i = 0; i < (uint32_t)imageInfoCount; ++i) {
            count_VkDescriptorImageInfo(sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                                        (const VkDescriptorImageInfo*)(pImageInfos + i), &count);
        }
    }
    count += 8;
    if (pBufferInfos) {
        for (uint32_t i = 0; i < (uint32_t)bufferInfoCount; ++i) {
            count_VkDescriptorBufferInfo(sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                                         (const VkDescriptorBufferInfo*)(pBufferInfos + i), &count);
        }
    }
    count += 8;
    if (pBufferViews) {
        if (bufferViewCount) {
            count += bufferViewCount * 8;
        }
    }
    count += 8;
    if (pInlineUniformBlockData) {
        count += inlineUniformBlockCount * sizeof(const uint8_t);
    }
    uint8_t* streamPtr = reservePacket(stream, OP_vkUpdateDescriptorSetWithTemplateSized2GOOGLE,
                                       count, queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_device_to_host_u64(device));
    writeStreamVal(&streamPtr, gfxstream_vk_descriptor_set_to_host_u64(descriptorSet));
    writeStreamVal(&streamPtr,
                   gfxstream_vk_descriptor_update_template_to_host_u64(descriptorUpdateTemplate));
    writeStreamBytes(&streamPtr, &imageInfoCount, sizeof(uint32_t));
    writeStreamBytes(&streamPtr, &bufferInfoCount, sizeof(uint32_t));
    writeStreamBytes(&streamPtr, &bufferViewCount, sizeof(uint32_t));
    writeStreamBytes(&streamPtr, &inlineUniformBlockCount, sizeof(uint32_t));
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pImageInfoEntryIndices);
    if (pImageInfoEntryIndices) {
        if (imageInfoCount > 0) {
            writeStreamBytes(&streamPtr, pImageInfoEntryIndices,
                             imageInfoCount * sizeof(const uint32_t));
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pBufferInfoEntryIndices);
    if (pBufferInfoEntryIndices) {
        if (bufferInfoCount > 0) {
            writeStreamBytes(&streamPtr, pBufferInfoEntryIndices,
                             bufferInfoCount * sizeof(const uint32_t));
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pBufferViewEntryIndices);
    if (pBufferViewEntryIndices) {
        if (bufferViewCount > 0) {
            writeStreamBytes(&streamPtr, pBufferViewEntryIndices,
                             bufferViewCount * sizeof(const uint32_t));
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pImageInfos);
    if (pImageInfos) {
        for (uint32_t i = 0; i < (uint32_t)imageInfoCount; ++i) {
            reservedmarshal_VkDescriptorImageInfo(stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                                                  (const VkDescriptorImageInfo*)(pImageInfos + i),
                                                  &streamPtr);
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pBufferInfos);
    if (pBufferInfos) {
        for (uint32_t i = 0; i < (uint32_t)bufferInfoCount; ++i) {
            reservedmarshal_VkDescriptorBufferInfo(
                stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                (const VkDescriptorBufferInfo*)(pBufferInfos + i), &streamPtr);
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pBufferViews);
    if (pBufferViews) {
        if (bufferViewCount) {
            for (uint32_t k = 0; k < bufferViewCount; ++k) {
                writeStreamVal(&streamPtr, gfxstream_vk_buffer_view_to_host_u64(pBufferViews[k]));
            }
        }
    }
    putBe64WithStreamPtr(&streamPtr, (uint64_t)(uintptr_t)pInlineUniformBlockData);
    if (pInlineUniformBlockData) {
        if (inlineUniformBlockCount > 0) {
            writeStreamBytes(&streamPtr, pInlineUniformBlockData,
                             inlineUniformBlockCount * sizeof(const uint8_t));
        }
    }
    stream->flush();
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

void VkEncoder::vkQueueSubmitAsync2GOOGLE(VkQueue queue, uint32_t submitCount,
                                          const VkSubmitInfo2* pSubmits, VkFence fence,
                                          uint32_t doLock) {
    bool queueSubmitWithCommandsEnabled =
        sFeatureBits & VULKAN_STREAM_FEATURE_QUEUE_SUBMIT_WITH_COMMANDS_BIT;
    if (!queueSubmitWithCommandsEnabled && doLock) this->lock();
    auto stream = mImpl->stream();
    auto pool = mImpl->pool();
    VkSubmitInfo2* local_pSubmits = nullptr;
    if (pSubmits) {
        local_pSubmits = (VkSubmitInfo2*)pool->alloc(submitCount * sizeof(const VkSubmitInfo2));
        for (uint32_t i = 0; i < (uint32_t)submitCount; ++i) {
            deepcopy_VkSubmitInfo2(pool, VK_STRUCTURE_TYPE_MAX_ENUM, pSubmits + i,
                                   (VkSubmitInfo2*)(local_pSubmits + i));
        }
    }
    if (local_pSubmits) {
        for (uint32_t i = 0; i < (uint32_t)submitCount; ++i) {
            transform_tohost_VkSubmitInfo2(sResourceTracker, (VkSubmitInfo2*)(local_pSubmits + i));
        }
    }
    size_t count = 0;
    count += 8;
    count += sizeof(uint32_t);
    for (uint32_t i = 0; i < (uint32_t)submitCount; ++i) {
        count_VkSubmitInfo2(sFeatureBits, VK_STRUCTURE_TYPE_MAX_ENUM,
                            (VkSubmitInfo2*)(local_pSubmits + i), &count);
    }
    count += 8;
    uint8_t* streamPtr =
        reservePacket(stream, OP_vkQueueSubmitAsync2GOOGLE, count, queueSubmitWithCommandsEnabled);
    writeStreamVal(&streamPtr, gfxstream_vk_queue_to_host_u64(queue));
    writeStreamBytes(&streamPtr, &submitCount, sizeof(uint32_t));
    for (uint32_t i = 0; i < (uint32_t)submitCount; ++i) {
        reservedmarshal_VkSubmitInfo2(stream, VK_STRUCTURE_TYPE_MAX_ENUM,
                                      (VkSubmitInfo2*)(local_pSubmits + i), &streamPtr);
    }
    writeStreamVal(&streamPtr, gfxstream_vk_fence_to_host_u64(fence));
    stream->flush();
    clearPoolIfNeeded(&encodeCount, mImpl->pool(), stream);
    if (!queueSubmitWithCommandsEnabled && doLock) this->unlock();
}

